"""Cardio dataset loading with a validated fallback chain.

Priority order (first success wins):
  1. local cache (REPRO_DATA_CACHE) or data/cardio.npz
  2. ADBench official artifact (Classical/6_cardio.npz) from GitHub raw
  3. sklearn.datasets.fetch_openml cardiotocography (id 1466), 21 features, NSP in {1,3}
  4. UCI Cardiotocography zip (id 193) -> CTG.xls, same filter

The 21 feature columns used by ADBench's cardio artifact are the numeric cardiotocography
variables in their original column order; we keep that order for the ADBench path and
reconstruct it for the OpenML/UCI paths.

Labels are returned separately and are never used by the scoring code (requirement R10).
"""
from __future__ import annotations

import io
import os
import zipfile

import numpy as np

# ADBench cardio artifact: 1831 samples, 21 features, 176 anomalies (9.61%).
EXPECTED_N = 1831
EXPECTED_D = 21
EXPECTED_ANOMALIES = 176

ADBENCH_RAW_URLS = [
    "https://raw.githubusercontent.com/Minqi824/ADBench/main/adbench/datasets/Classical/6_cardio.npz",
    "https://raw.githubusercontent.com/Minqi824/ADBench/master/adbench/datasets/Classical/6_cardio.npz",
]

CACHE_NAMES = [
    "6_cardio.npz",
    "cardio.npz",
    "cardio_adbench.npz",
]

# 21 ADBench cardio feature columns (order matters: matches the ADBench artifact).
ADBENCH_CARDIO_FEATURES = [
    "LB", "AC", "FM", "UC", "DL", "DS", "DP", "ASTV", "MSTV", "ALTV", "MLTV",
    "Width", "Min", "Max", "Nmax", "Nzeros", "Mode", "Mean", "Median", "Variance",
    "Tendency",
]

OPENML_NAMES = {
    "LB": "LB", "AC": "AC", "FM": "FM", "UC": "UC", "DL": "DL", "DS": "DS", "DP": "DP",
    "ASTV": "ASTV", "MSTV": "MSTV", "ALTV": "ALTV", "MLTV": "MLTV", "Width": "Width",
    "Min": "Min", "Max": "Max", "Nmax": "Nmax", "Nzeros": "Nzeros", "Mode": "Mode",
    "Mean": "Mean", "Median": "Median", "Variance": "Variance", "Tendency": "Tendency",
}


def _cache_dirs() -> list[str]:
    dirs = []
    env = os.environ.get("REPRO_DATA_CACHE")
    if env:
        dirs.append(env)
    dirs.append(os.path.join(os.path.dirname(os.path.dirname(os.path.abspath(__file__))), "data"))
    return dirs


def _validate(X: np.ndarray, y: np.ndarray, source: str) -> dict:
    info = {
        "source": source,
        "n": int(X.shape[0]),
        "d": int(X.shape[1]),
        "n_anomalies": int(y.sum()),
        "anomaly_rate": float(y.mean()),
        "has_nan": bool(np.isnan(X).any() or np.isinf(X).any()),
        "signature_ok": bool(
            X.shape == (EXPECTED_N, EXPECTED_D)
            and int(y.sum()) == EXPECTED_ANOMALIES
            and not np.isnan(X).any()
        ),
    }
    return info


def _from_adbench_npz(path: str, source: str):
    d = np.load(path, allow_pickle=True)
    X = np.asarray(d["X"], dtype=np.float64)
    y = np.asarray(d["y"]).ravel().astype(np.int64)
    return X, y, _validate(X, y, source)


def _download_adbench(dest_dir: str):
    try:
        import requests
    except ImportError:
        return None
    os.makedirs(dest_dir, exist_ok=True)
    dest = os.path.join(dest_dir, "6_cardio.npz")
    for url in ADBENCH_RAW_URLS:
        try:
            r = requests.get(url, timeout=60)
            if r.status_code == 200 and len(r.content) > 1000:
                with open(dest, "wb") as fh:
                    fh.write(r.content)
                return dest
        except Exception:
            continue
    return None


def _from_openml():
    from sklearn.datasets import fetch_openml

    for kwargs in ({"data_id": 1466}, {"name": "cardiotocography"}):
        try:
            bunch = fetch_openml(**kwargs, as_frame=True)
        except Exception:
            continue
        df = bunch.frame
        cols = []
        for f in ADBENCH_CARDIO_FEATURES:
            cand = [c for c in df.columns if str(c).split(".")[-1].strip() == f]
            if not cand:
                cols = []
                break
            cols.append(cand[0])
        if not cols:
            continue
        nsp_cand = [c for c in df.columns if str(c).split(".")[-1].strip() == "NSP"]
        if not nsp_cand:
            continue
        nsp = df[nsp_cand[0]].astype(float).to_numpy()
        keep = (nsp == 1) | (nsp == 3)
        Xdf = df.loc[keep, cols].astype(np.float64)
        X = Xdf.to_numpy()
        y = (nsp[keep] == 3).astype(np.int64)
        return X, y, _validate(X, y, "openml_cardiotocography(%s)" % kwargs)
    return None


def _from_uci_zip(dest_dir: str):
    try:
        import requests
        import pandas as pd
    except ImportError:
        return None
    urls = [
        "https://archive.ics.uci.edu/static/public/193/cardiotocography.zip",
        "https://archive.ics.uci.edu/ml/machine-learning-databases/00193/CTG.xls",
    ]
    os.makedirs(dest_dir, exist_ok=True)
    for url in urls:
        try:
            r = requests.get(url, timeout=120)
            if r.status_code != 200 or len(r.content) < 1000:
                continue
            if url.endswith(".zip"):
                zf = zipfile.ZipFile(io.BytesIO(r.content))
                xls = [n for n in zf.namelist() if n.lower().endswith((".xls", ".xlsx"))]
                if not xls:
                    continue
                raw = zf.read(xls[0])
            else:
                raw = r.content
            sheets = pd.read_excel(io.BytesIO(raw), sheet_name=None)
            for name, df in sheets.items():
                if "NSP" in df.columns and "LB" in df.columns:
                    keep = df["NSP"].isin([1, 3])
                    sub = df.loc[keep, ADBENCH_CARDIO_FEATURES]
                    X = sub.astype(np.float64).to_numpy()
                    y = (df.loc[keep, "NSP"].astype(float).to_numpy() == 3).astype(np.int64)
                    if np.isnan(X).any():
                        continue
                    return X, y, _validate(X, y, "uci_ctg_xls")
        except Exception:
            continue
    return None


