"""Evaluation metrics; scores first, labels second (labels only used post-prediction, R9/R10)."""
from __future__ import annotations

import numpy as np
from sklearn.metrics import average_precision_score, precision_recall_curve, roc_auc_score


def roc_auc(scores, y) -> float:
    return float(roc_auc_score(np.asarray(y), np.asarray(scores)))


def auc_pr_ap(scores, y) -> float:
    """Average precision, the AUC-PR convention used by ADBench / PyOD."""
    return float(average_precision_score(np.asarray(y), np.asarray(scores)))


def auc_pr_trapz(scores, y) -> float:
    """Trapezoidal area under the precision-recall curve (secondary variant)."""
    p, r, _ = precision_recall_curve(np.asarray(y), np.asarray(scores))
    return float(np.trapezoid(p, r) if hasattr(np, "trapezoid") else np.trapz(p, r))


def summarize(values) -> dict:
    v = np.asarray(list(values), dtype=np.float64)
    return {
        "mean": float(v.mean()),
        "std": float(v.std(ddof=1)) if v.size > 1 else 0.0,
        "min": float(v.min()),
        "max": float(v.max()),
        "n": int(v.size),
    }

